package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveClaim {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            @Val ClaimInput input, ServerHttpConnection connection, ClaimRepository repository,
            SheetRepository sheets, PeriodRepository periods, PersonRepository people, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long cid;
        try {
            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such claim");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        // Only a draft can be edited: to change an open claim, void it and add a new one.
        if (!found.status().equals("DRAFT")) {
            throw new BadRequestException("a " + found.status() + " claim cannot be edited");
        }
        String holder = repository.lockedBy(id, cid);
        if (holder != null && !holder.equals(by)) {
            throw new BadRequestException("the claim is being edited by " + holder);
        }
        LocalDate date = input.date() != null ? input.date() : sheets.today(id);
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        people.claimAllowed(id, found.personId(), date);
        input.checkCorrection(repository, id, found.personId());
        input.checkRef(repository, id, cid);
        // A claim's due-by is fixed when it is created: editing its date leaves it as it is.
        String dueBy = found.dueBy();
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.update(id, cid, input.amount(), date, LocalDate.parse(dueBy), input.note(), input.corrects(), input.ref(), input.tags())) {
            throw new BadRequestException("only a DRAFT claim can be edited");
        }
        repository.editedBy(id, cid, by);
        repository.unlock(id, cid, by);
        long pid = found.personId();
        Claim saved = new Claim(cid, pid, ClaimRepository.money(input.amount()), date.toString(), input.note(),
                found.status(), found.number(), found.due(), found.openedBy(), found.stated(), found.statedDue(), input.corrects(),
                dueBy, found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), input.ref(), input.tags(), found.voidReason());
        audit.record("CLAIM_EDITED sheet=" + id + " by=" + by + " person=" + repository.personName(id, pid)
                + " amount=" + saved.amount() + " date=" + saved.date() + Claim.auditNumber(saved.number()));
        rollup.record(id, by, before);
        claim.set(saved);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;

/** A validated claim form: the amount (negative for a correction), the date ({@code null} when left blank:
 *  the sheet's today), the note, and the number of the claim a correction corrects ({@code null} when left blank), and its external reference (trimmed;
 *  {@code null} when left blank), and its tags (see {@link Claim#tags(String)}; {@code null} when none). */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {

    private static final Pattern SIGNED = Pattern.compile("-?(\\d+(\\.\\d{1,2})?|\\.\\d{1,2})");

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?|\\.\\d{1,2}");

    /** A typed amount (trimmed): required, a number with up to two decimals, 0.00 or more. */
    public static BigDecimal amount(String amount) throws BadRequestException {
        if (amount.isEmpty()) {
            throw new BadRequestException("amount is required");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new BadRequestException("amount must be a number of 0.00 or more with up to two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** A typed claim-form amount (trimmed): required, a number with up to two decimals; a negative one
     *  is a correction. */
    public static BigDecimal signedAmount(String amount) throws BadRequestException {
        if (amount.isEmpty()) {
            throw new BadRequestException("amount is required");
        }
        if (!SIGNED.matcher(amount).matches()) {
            throw new BadRequestException("amount must be a number with up to two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** Check the external reference against the sheet: one already used by another claim on it (other than
     *  {@code exceptId}, null: none), comparing without regard to case, is refused. */
    public void checkRef(ClaimRepository repository, String sheetId, Long exceptId) throws BadRequestException {
        if (ref != null && repository.refUsed(sheetId, ref, exceptId)) {
            throw new BadRequestException("reference " + ref + " is already used on the sheet");
        }
    }

    /** Whether the amount is a correction's: below zero. */
    public boolean correction() {
        return amount.signum() < 0;
    }

    /** Check the form against the person's claims: a negative amount must name, by number, a SETTLED
     *  claim of the same person; only a negative amount may name one. */
    public void checkCorrection(ClaimRepository repository, String sheetId, long personId) throws BadRequestException {
        if (!correction()) {
            if (corrects != null) {
                throw new BadRequestException("only a negative amount corrects a claim");
            }
            return;
        }
        if (corrects == null) {
            throw new BadRequestException("a negative amount is a correction: name the settled claim it corrects");
        }
        if (!repository.settledOf(sheetId, personId, corrects)) {
            throw new BadRequestException("claim " + corrects + " is not a settled claim of this person");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.person.Hold;

/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED, VOID or DELETED — a deleted DRAFT, counted nowhere), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
 *  (null until it is opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound with no figure: its due then stays live), and, for a correction (a negative
 *  amount), the number of the settled claim it corrects (null otherwise), and its due-by (yyyy-MM-dd: fixed when it was
 *  created, its date then plus its person's own terms, else the terms of their grade on that date, else the sheet's terms), and
 *  whether its last statement bound it to n/a (the rate that would apply to it had ended: its due then
 *  stays n/a, not live), and the date it is deferred until (null when never deferred) and whether it is
 *  deferred now (OPEN and that date after the sheet's today: it then counts in no total, is not overdue,
 *  cannot be settled and a statement leaves it unbound), and how many proofs it has been given, and, for a claim
 *  split off another, the number of the claim it was split from (null otherwise), and whether it was a late entry
 *  (added while the period its due-by falls in was soft-closed), and the last day (the sheet's today then) a reminder
 *  was written for it (null when never reminded), and its external reference (null when none), and its tags (lower-case, sorted and
 *  comma separated, with no spaces; null when none), and the reason it was voided with (one of its sheet's void reasons; null when none was given). */
public record Claim(long id, long personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String dueBy, boolean statedNa, String deferredUntil, boolean deferred, int proofs, String splitFrom,
        boolean lateEntry, String reminded, String ref, String tags, String voidReason) {

    /** Whether the claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
    public boolean open() {
        return status.equals("OPEN") || status.equals("PENDING");
    }

    /** Whether the claim counts toward claimed and every total: only open (OPEN or PENDING) and SETTLED claims do. */
    public boolean counts() {
        return open() || status.equals("SETTLED");
    }

    /** Whether the claim counts toward live totals (claimed, due-totals, a period's total) given its
     *  person's holds: an open claim dated within a hold does not, unless a statement binds it; SETTLED
     *  claims always do. A deferred claim does not. */
    public boolean counts(List<Hold> holds) {
        return status.equals("SETTLED") || (open() && !deferred && (bound() || !Hold.anyCovers(holds, date)));
    }

    /** Whether the claim counts toward a period ending on a day, given the status it had at the end of that
     *  day (null when it did not exist then: it does not count) and its person's holds: the live rules
     *  applied to that status (an open claim deferred until after the sheet's today does not count either). A hold
     *  leaves out only a claim still open now: one since settled or voided counts by the status it had then. */
    public boolean countsAs(String statusThen, List<Hold> holds, String today) {
        if (statusThen == null) return false;
        boolean deferredNow = statusThen.equals("OPEN") && deferredUntil != null && today != null && today.compareTo(deferredUntil) < 0;
        Claim then = new Claim(id, personId, amount, date, note, statusThen, number, due, openedBy, stated, statedDue,
                corrects, dueBy, statedNa, deferredUntil, deferredNow, proofs, splitFrom, lateEntry, reminded, ref, tags, voidReason);
        return then.counts(open() ? holds : List.of());
    }

    /** Whether the claim keeps a fixed figure: its settled due, else the one its last statement bound it
     *  to — except while PENDING, when the statement does not bind it and its figure is live. */
    public boolean fixed() {
        return due != null || (bound() && statedDue != null);
    }

    /** Whether its last statement binds it now: it was stated and is not PENDING. */
    public boolean bound() {
        return stated && !status.equals("PENDING");
    }

    /** The audit field a numbered claim adds at the end of its lines: " number=<n>", or "" when it has none. */
    static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }

    /** The audit field a claim with an external reference adds at the end of CLAIM_ADDED: " ref=<reference>", or "" when it has none. */
    public static String auditRef(String ref) {
        return ref == null ? "" : " ref=" + ref;
    }

    /** The audit field a claim with tags adds at the end of CLAIM_ADDED: " tags=<comma separated, sorted>", or "" when it has none. */
    public static String auditTags(String tags) {
        return tags == null ? "" : " tags=" + tags;
    }

    /** Typed tags as a claim keeps them: split on commas, each trimmed and lower-cased, blanks and repeats
     *  dropped, sorted and joined with commas; null when none is left. */
    public static String tags(String typed) {
        if (typed == null) return null;
        java.util.TreeSet<String> set = new java.util.TreeSet<>();
        for (String t : typed.split(",")) {
            String tag = t.trim().toLowerCase(java.util.Locale.ROOT);
            if (!tag.isEmpty()) set.add(tag);
        }
        return set.isEmpty() ? null : String.join(",", set);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;

/** A claim's editor lock: opening the editor (the edit button) locks the claim for every other user until its
 *  editor is saved or cancelled, or the sheet's today changes. Only a DRAFT outside a closed period can be
 *  edited: any other claim is refused and takes no lock, as is a claim another user holds. A refusal writes nothing. */
final class ClaimLock {
    private ClaimLock() {
    }

    static Claim lock(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods)
            throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!found.status().equals("DRAFT")) {
            throw new BadRequestException("only a DRAFT claim can be edited");
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        if (!repository.lock(id, found, by)) {
            throw new BadRequestException("the claim is being edited by " + repository.lockedBy(id, cid));
        }
        return found;
    }

    static Claim unlock(String id, long cid, String by, ClaimRepository repository) throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        repository.unlock(id, cid, by);
        return found;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;

/** Raise a claim's proofs count by one: not a SETTLED, VOID or DELETED claim, nor one in a closed period. Every check is
 *  made before anything is written, so a refusal writes nothing to the store or the audit. */
final class ClaimProof {
    private ClaimProof() {
    }

    static Claim apply(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
            Audit audit) throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (found.status().equals("SETTLED") || found.status().equals("VOID") || found.status().equals("DELETED")) {
            throw new BadRequestException("a " + found.status() + " claim cannot be given a proof");
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        Integer proofs = repository.addProof(id, cid);
        if (proofs == null) {
            throw new BadRequestException("a " + found.status() + " claim cannot be given a proof");
        }
        audit.record("CLAIM_PROOF_ADDED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + found.amount() + " date=" + found.date() + Claim.auditNumber(found.number())
                + " proofs=" + proofs);
        return repository.find(id, cid);
    }
}

